// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import {
    signIn,
    applyHighlightColorFilter,
    openHighlightNoteEditor,
    saveHighlightNote,
    highlightCard,
} from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(188000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    // Credential(s) read from the environment — never recorded into this file. Set these before running.
    if (process.env.SKYRAMP_UI_PASSWORD === undefined) {
        throw new Error("SKYRAMP_UI_PASSWORD is not set: this test replays a login and needs that credential in the environment");
    }
    const loginPassword = process.env.SKYRAMP_UI_PASSWORD ?? "";

    await signIn(page, baseUrl, "testbot-admin", loginPassword);

    await page.locator('#sidebar a[href="/highlights"]').click();

    await applyHighlightColorFilter(page, "highlight-color-green");
    await expect(page.getByTestId("highlight-text")).toContainText("Second fixture passage in green");
    await expect(page.getByText("Testbot fixture highlight passage", { exact: true })).toBeHidden();

    await applyHighlightColorFilter(page, "highlight-color-all");
    await expect(page.getByText("Testbot fixture highlight")).toContainText("Testbot fixture highlight passage");

    await openHighlightNoteEditor(page, "Testbot fixture highlight passage");

    const playwrightRequest0: Record<string, any> = {"comment": "Testbot note saved in place"};

    const response0 = await saveHighlightNote(page, "Testbot fixture highlight passage", getValue(playwrightRequest0, "comment"));

    expect(response0.status(), 'PATCH status').toBe(200);
    const response0Body = await response0.json();
    expect(response0Body.response.comment, 'saved note').toBe("Testbot note saved in place");
    expect(response0Body.response.color, 'colour untouched by a comment-only save').toBe("yellow");
    await expect(highlightCard(page, "Testbot fixture highlight passage").getByTestId("highlight-note")).toContainText("Testbot note saved in place");
});
